import{renderDiagram}from './visual.js?v=20261022-eco4';import{familyFigure}from './family-figures.js?v=20261022-eco4';export function showFamily(spec='pedigree',w={}){let kind=spec.split(':')[0];renderDiagram(w.title||({pedigree:'Follow the family evidence',cross:'Build the genetic cross',screening:'Weigh evidence and perspectives',sex:'Follow the chromosome contributions'})[kind]||'Inheritance: evidence and probability',w.label||'Original educational schematic',familyFigure({kind,...w}),'FAMILIES AND GENETIC EVIDENCE');}
